target.css:
:root {
  --ink: #252138;
  --plum: #49345d;
  --cream: #fffaf0;
  --peach: #f5d5bf;
  --coral: #d96657;
  --mint: #b8dccb;
  --line: #ded3c7;
}

.broth-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--cream);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px;
  color: var(--cream);
  background: var(--plum);
}

.kicker {
  margin: 0 0 3px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.2px;
}

h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1;
}

.batch-chip {
  padding: 5px 8px;
  color: var(--plum);
  background: var(--peach);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.recipe-grid {
  display: grid;
  grid-template-columns: 126px 1fr;
  gap: 16px;
  padding: 14px 16px;
}

.visual-panel {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin: 0;
  padding: 10px;
  background: var(--peach);
  border-radius: 12px;
}

.pot-icon {
  font-size: 39px;
  line-height: 1;
}

.visual-panel p {
  margin: 7px 0 0;
  font-size: 11px;
  font-weight: 700;
}

.details h2 {
  margin: 2px 0 9px;
  font-size: 15px;
  line-height: 1.1;
}

.metric-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
}

.metric {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
  padding: 6px 8px;
  background: var(--cream);
  border: 1px solid var(--line);
  border-radius: 7px;
}

.metric span {
  font-size: 10px;
  color: var(--plum);
}

.metric strong {
  font-size: 12px;
}

footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
}

.status {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  font-size: 12px;
  font-weight: 700;
}

.status span {
  width: 8px;
  height: 8px;
  background: var(--mint);
  border-radius: 50%;
}

button {
  padding: 7px 11px;
  color: var(--cream);
  background: var(--coral);
  border: 0;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 800;
}

